WITH exploded AS (SELECT id, service, latency_ms, k, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) x AS k, attr_value), enriched AS (SELECT id, service, k, attr_value, AVG(latency_ms) OVER (ORDER BY latency_ms ASC, id ASC, k ASC ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS latency_ms_avg_5, SUM(latency_ms) OVER (PARTITION BY service ORDER BY latency_ms ASC, id ASC, k ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_latency_ms FROM exploded), enriched_app_logs AS (SELECT id, k, attr_value, latency_ms_avg_5, FIRST_VALUE(running_latency_ms, TRUE) OVER (ORDER BY running_latency_ms ASC, id ASC, k ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_running_latency_ms, AVG(running_latency_ms) OVER (PARTITION BY k, service ORDER BY latency_ms_avg_5 ASC, id ASC, k ASC ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS running_latency_ms_avg_6_prior, ROW_NUMBER() OVER (PARTITION BY k ORDER BY running_latency_ms DESC, id ASC, k ASC) AS seq_no FROM enriched WHERE service = 'billing'), metrics AS (SELECT *, MIN(first_known_running_latency_ms) OVER w_hist AS running_min_first_known_running_latency_ms, SUM(first_known_running_latency_ms) OVER w_hist AS running_sum_first_known_running_latency_ms, COUNT(first_known_running_latency_ms) OVER w_hist AS running_count_first_known_running_latency_ms, ROW_NUMBER() OVER (PARTITION BY k ORDER BY seq_no DESC, id ASC, k ASC) AS row_seq FROM enriched_app_logs WINDOW w_hist AS (PARTITION BY k ORDER BY running_latency_ms_avg_6_prior ASC, id ASC, k ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), scored AS (SELECT *, RANK() OVER (ORDER BY running_latency_ms_avg_6_prior DESC NULLS LAST) AS running_latency_ms_avg_6_prior_rank, ROW_NUMBER() OVER (PARTITION BY k ORDER BY row_seq ASC, id ASC, k ASC) AS row_seq_2, NTILE(10) OVER (PARTITION BY k ORDER BY row_seq ASC, id ASC, k ASC) AS row_seq_bucket FROM metrics), with_windows AS (SELECT id, k, attr_value, latency_ms_avg_5, running_latency_ms_avg_6_prior, running_sum_first_known_running_latency_ms, running_count_first_known_running_latency_ms, MIN(running_latency_ms_avg_6_prior_rank) OVER w_part AS k_min_running_latency_ms_avg_6_prior_rank, NTILE(10) OVER (PARTITION BY k ORDER BY first_known_running_latency_ms ASC, id ASC, k ASC) AS first_known_running_latency_ms_bucket, ROW_NUMBER() OVER (PARTITION BY k ORDER BY row_seq DESC, id ASC, k ASC) AS event_seq FROM scored WINDOW w_part AS (PARTITION BY k)), enriched_app_logs_2 AS (SELECT *, NTILE(5) OVER (PARTITION BY k ORDER BY running_sum_first_known_running_latency_ms ASC, id ASC, k ASC) AS running_sum_first_known_running_latency_ms_bucket, NTILE(4) OVER (ORDER BY event_seq ASC, id ASC, k ASC) AS event_seq_bucket, SUM(running_sum_first_known_running_latency_ms) OVER (PARTITION BY k) AS k_sum_running_sum_first_known_running_latency_ms FROM with_windows) SELECT id, k, attr_value, latency_ms_avg_5, running_sum_first_known_running_latency_ms, running_count_first_known_running_latency_ms, first_known_running_latency_ms_bucket, event_seq_bucket, k_sum_running_sum_first_known_running_latency_ms FROM enriched_app_logs_2 ORDER BY id DESC NULLS LAST, latency_ms_avg_5 ASC;
